def next_action(result):
    status = result.get("status", "unknown")
    process_id = result.get("process_id")

    if status == "running":
        return {"tool": "get_process_status", "process_id": process_id}
    elif status == "completed" and result.get("exit_code") == 0:
        return {"tool": "final_report", "success": True}
    elif status == "completed":
        return {"tool": "final_report", "success": False}
    else:
        raise ValueError("Unknown status")

from protocol import next_action

def test_running_status():
    result = {"status": "running", "process_id": 12345}
    expected = {"tool": "get_process_status", "process_id": 12345}
    assert next_action(result) == expected, f"Expected {expected}, got {next_action(result)}"

def test_completed_success():
    result = {"status": "completed", "exit_code": 0}
    expected = {"tool": "final_report", "success": True}
    assert next_action(result) == expected, f"Expected {expected}, got {next_action(result)}"

def test_completed_failure():
    result = {"status": "completed", "exit_code": 1}
    expected = {"tool": "final_report", "success": False}
    assert next_action(result) == expected, f"Expected {expected}, got {next_action(result)}"

def test_unknown_status():
    result = {"status": "unknown"}
    try:
        next_action(result)
        assert False, "Should have raised ValueError"
    except ValueError:
        pass

if __name__ == "__main__":
    test_running_status()
    test_completed_success()
    test_completed_failure()
    test_unknown_status()
    print("All tests passed")
